// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "../bridge";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface BloodUnitOut {
  unit_id: number;
  source_id: number;
  source_name: string;
  unit_number: string;
  component: "WholeBlood" | "RedCells" | "FreshFrozenPlasma" | "Cryoprecipitate" | "Platelets";
  abo: "A" | "B" | "AB" | "O";
  rh: "Positive" | "Negative";
  volume_ml: number | null;
  collected_on: string | null;
  expires_at: string;
  /** The expiry has passed: discard it */
  expired: boolean;
  screened: boolean;
  arrival_temperature_c: number | null;
  received_at: string;
  received_by: number;
  status: "InStock" | "Reserved" | "Issued" | "Transfused" | "Discarded" | "ReturnedToSource";
  /** The request it is cross-matched for (kept once issued) */
  reserved_for: number | null;
  reserved_for_number: string | null;
  discard_reason: "Expired" | "BagDamaged" | "OutOfStorageTooLong" | "StorageTemperature" | "IdentityDiscrepancy" | "Other" | null;
  status_note: string | null;
  status_at: string;
  status_by: number | null;
  /** Released by the hospital's own blood center: its component */
  center_component_id: number | null;
  /** Its donation (GET /blood-center/donations/{donation_id}), back to the donor */
  donation_id: number | null;
  donation_number: string | null;
  row_version: number;
}

/** A bag received into the blood bank, as its label says (never rewritten afterwards). */
export interface BloodUnitIn {
  source_id: number;
  /** The number on the bag, as the source printed it */
  unit_number: string;
  component: "WholeBlood" | "RedCells" | "FreshFrozenPlasma" | "Cryoprecipitate" | "Platelets";
  abo: "A" | "B" | "AB" | "O";
  rh: "Positive" | "Negative";
  volume_ml?: number | null;
  collected_on?: string | null;
  /** The expiry on the label; an expired unit is refused */
  expires_at: string;
  /** The label or the issue note says the unit was screened (hepatitis B and C, HIV, malaria, syphilis: II C manual p154). Must be true: an unscreened unit is not received */
  screened: boolean;
  /** The bag's temperature on arrival */
  arrival_temperature_c?: number | string | null;
}

